import os
import numpy as np


class Config:
    """
    Configuration class for the Hyper-Densified Global-Gaussianized LDA Ensemble.
    Centralizes all hyperparameters, file paths, and topology settings.
    """

    # ==========================================
    # 1. Paths & Directories
    # ==========================================
    INPUT_DIR = "./input"
    METADATA_DIR = "./metadata"
    WORKING_DIR = "./working/idea_15"
    SUBMISSION_DIR = "./submission"
    IMAGES_DIR = os.path.join(INPUT_DIR, "images")

    # Metadata Files (Generated by metadata script)
    TRAIN_METADATA = os.path.join(METADATA_DIR, "train.csv")
    VAL_METADATA = os.path.join(METADATA_DIR, "val.csv")
    TEST_METADATA = os.path.join(METADATA_DIR, "test.csv")

    # Output Files
    SUBMISSION_PATH = os.path.join(SUBMISSION_DIR, "submission.csv")

    # ==========================================
    # 2. Experiment Settings
    # ==========================================
    SEED = 42
    N_FOLDS = 10  # Stratified K-Fold

    # Debugging flags
    DEBUG = False
    DEBUG_SAMPLES = 50  # Number of samples to use when DEBUG is True

    # ==========================================
    # 3. Model Architecture & Feature Extraction
    # ==========================================
    # Dual-Stream Architecture
    MODEL_DINO = "vit_large_patch14_dinov2"  # Global Geometry Stream
    MODEL_CONVNEXT = "convnext_large"  # Local Texture Stream

    # DataLoader Parameters
    IMG_SIZE = 224
    BATCH_SIZE = 32
    NUM_WORKERS = 4

    # ==========================================
    # 4. Topology & Hyper-Densification
    # ==========================================
    # Rotation Logic: 36 equidistant views (0, 10, ..., 350)
    ROTATION_START = 0
    ROTATION_END = 360
    ROTATION_STEP = 10
    ROTATION_ANGLES = list(range(ROTATION_START, ROTATION_END, ROTATION_STEP))
    NUM_VIEWS = len(ROTATION_ANGLES)  # 36 views

    # Hyper-Densification (Training): 9 Orthogonal Centroids per image
    # Each centroid is the average of 4 mutually exclusive orthogonal views.
    # Centroid k uses indices: {k, k+9, k+18, k+27} corresponding to {0+10k, 90+10k, 180+10k, 270+10k} degrees
    ORTHOGONAL_SETS = []
    for k in range(9):
        # 90 degrees = 9 steps of 10 degrees
        indices = [k, k + 9, k + 18, k + 27]
        ORTHOGONAL_SETS.append(indices)

    # Canonical Centroid (Inference/Validation):
    # Single centroid per image using the standard orthogonal axes (0, 90, 180, 270)
    CANONICAL_SET = ORTHOGONAL_SETS[0]

    # ==========================================
    # 5. Feature Engineering & Classifier
    # ==========================================
    # Independent Subspace Reduction
    PCA_VARIANCE = 0.99  # Retain 99% variance for each stream independently

    # Global Feature Gaussianization
    QUANTILE_OUTPUT_DIST = "normal"  # Transform features to Gaussian distribution

    # Probability Clipping (to avoid log loss extremes)
    PROB_CLIP = 1e-15

    # ==========================================
    # 6. Caching System
    # ==========================================
    # Paths for caching extracted features to optimize runtime
    # We cache the raw 36-view features before densification/averaging

    # Train Split (from metadata/train.csv)
    CACHE_TRAIN_DINO = os.path.join(WORKING_DIR, "train_dino_features.npy")
    CACHE_TRAIN_CONVNEXT = os.path.join(WORKING_DIR, "train_convnext_features.npy")
    CACHE_TRAIN_TABULAR = os.path.join(WORKING_DIR, "train_tabular_features.npy")
    CACHE_TRAIN_IDS = os.path.join(WORKING_DIR, "train_ids.npy")
    CACHE_TRAIN_LABELS = os.path.join(WORKING_DIR, "train_labels.npy")

    # Val Split (from metadata/val.csv)
    CACHE_VAL_DINO = os.path.join(WORKING_DIR, "val_dino_features.npy")
    CACHE_VAL_CONVNEXT = os.path.join(WORKING_DIR, "val_convnext_features.npy")
    CACHE_VAL_TABULAR = os.path.join(WORKING_DIR, "val_tabular_features.npy")
    CACHE_VAL_IDS = os.path.join(WORKING_DIR, "val_ids.npy")
    CACHE_VAL_LABELS = os.path.join(WORKING_DIR, "val_labels.npy")

    # Test Split (from metadata/test.csv)
    CACHE_TEST_DINO = os.path.join(WORKING_DIR, "test_dino_features.npy")
    CACHE_TEST_CONVNEXT = os.path.join(WORKING_DIR, "test_convnext_features.npy")
    CACHE_TEST_TABULAR = os.path.join(WORKING_DIR, "test_tabular_features.npy")
    CACHE_TEST_IDS = os.path.join(WORKING_DIR, "test_ids.npy")

    @classmethod
    def setup(cls):
        """
        Initialize the working environment by creating necessary directories.
        """
        os.makedirs(cls.WORKING_DIR, exist_ok=True)
        os.makedirs(cls.SUBMISSION_DIR, exist_ok=True)
